import numpy as np

def solve(data):
    n = data['n']
    edges = data['edges']
    source = data['source']

    # Initialize the distance matrix with infinity
    dist_matrix = np.full((n, n), float('inf'))
    dist_matrix[source, source] = 0

    # Populate the distance matrix with edge weights
    for u, v, weight in edges:
        dist_matrix[u, v] = weight

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist_matrix[i, j] = min(dist_matrix[i, j], dist_matrix[i, k] + dist_matrix[k, j])

    # Convert the distance matrix to a list of lists
    result = []
    for i in range(n):
        if dist_matrix[source, i] != float('inf'):
            result.append(dist_matrix[source, i])
        else:
            result.append(None)

    return result

import numpy as np

def solve(data):
    grid = data['grid']

    # Convert list of lists to numpy array for efficient computation
    grid_np = np.array(grid)

    # Initialize the grid with infinity except for the starting point
    dp = np.full_like(grid_np, np.inf)
    dp[0, 0] = 0

    # Fill the DP table
    for i in range(1, len(grid)):
        dp[i, 0] += grid_np[i, 0]
    for j in range(1, len(grid[0])):
        dp[0, j] += grid_np[0, j]
    for i in range(1, len(grid)):
        for j in range(1, len(grid[0])):
            dp[i, j] = min(dp[i - 1, j], dp[i, j - 1]) + grid_np[i, j]

    # If the bottom-right corner is still infinity, there is no valid path
    if dp[-1, -1] == np.inf:
        return None

    return dp[-1, -1]

