import numpy as np

def solve(data):
    grid = data['grid']
    rows, cols = len(grid), len(grid[0])

    # If the grid is empty, return None
    if rows == 0 or cols == 0:
        return None

    # Initialize a 2D array with the same dimensions as the grid
    dp = np.zeros((rows, cols))

    # Set the starting point cost to 0
    dp[0][0] = grid[0][0]

    # Fill the first row and column of the DP table
    for i in range(1, rows):
        dp[i][0] += dp[i-1][0] + grid[i][0]
    for j in range(1, cols):
        dp[0][j] += dp[0][j-1] + grid[0][j]

    # Fill the rest of the DP table
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] != -1:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # If the bottom-right corner is -1, there is no valid path
    if dp[-1][-1] == -1:
        return None

    return dp[-1][-1]

import numpy as np

def solve(data):
    # Check for empty grid
    if not data['grid']:
        return None

    # Convert grid to numpy array for easier manipulation
    grid = np.array(data['grid'])

    # Initialize the DP table with zeros
    dp = np.zeros_like(grid)

    # Fill the DP table
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == -1:
                continue
            if i == 0 and j == 0:
                dp[i][j] = grid[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j-1] + grid[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + grid[i][j]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # If the destination is not reachable, return None
    if dp[-1][-1] == float('inf'):
        return None

    # Return the minimum cost
    return int(dp[-1][-1])

