import numpy as np

def solve(data):
    grid = data['grid']

    # Check for empty grid
    if not grid:
        return None

    # Convert grid to numpy array for easier manipulation
    grid_array = np.array(grid)

    # Initialize the same size array with zeros
    min_cost = np.zeros_like(grid_array)

    # Set the starting point cost to 0
    min_cost[0, 0] = grid_array[0, 0]

    # Fill the first row
    for j in range(1, grid_array.shape[1]):
        min_cost[0, j] = min_cost[0, j-1] + grid_array[0, j]

    # Fill the first column
    for i in range(1, grid_array.shape[0]):
        min_cost[i, 0] = min_cost[i-1, 0] + grid_array[i, 0]

    # Fill the rest of the grid
    for i in range(1, grid_array.shape[0]):
        for j in range(1, grid_array.shape[1]):
            if grid_array[i, j] == -1:
                min_cost[i, j] = float('inf')
            else:
                min_cost[i, j] = min(min_cost[i-1, j], min_cost[i, j-1]) + grid_array[i, j]

    # Check if there was an obstacle at the end
    if min_cost[-1, -1] == float('inf'):
        return None

    return int(min_cost[-1, -1])

