class Solution:
    def solve(self, data: Dict[str, Any]) -> Any:
        grid = data["grid"]

        # Edge cases
        if not grid or not grid[0]:
            return None

        rows, cols = len(grid), len(grid[0])

        # Initialize the DP table with infinity
        dp = [[float('inf')] * cols for _ in range(rows)]

        # Base case: the starting point has zero cost
        dp[0][0] = 0

        # Fill the DP table
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == -1:
                    continue

                # Calculate the cost of moving right
                if i > 0:
                    dp[i][j] = min(dp[i][j], dp[i-1][j] + grid[i][j])

                # Calculate the cost of moving down
                if j > 0:
                    dp[i][j] = min(dp[i][j], dp[i][j-1] + grid[i][j])

        # If the destination cell has no path, return None
        if dp[-1][-1] == float('inf'):
            return None

        return dp[-1][-1]

