import numpy as np

def solve(data):
    grid = data['grid']
    rows, cols = len(grid), len(grid[0])

    # Create a DP table with dimensions (rows+1) x (cols+1)
    dp = np.zeros((rows + 1, cols + 1))

    # Fill the DP table using dynamic programming
    for i in range(1, rows + 1):
        for j in range(1, cols + 1):
            if grid[i-1][j-1] == -1:
                continue
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i-1][j-1]

    # If there is no valid path, return None
    if dp[-1][-1] == 0:
        return None

    # Reconstruct the path from the DP table
    path = []
    i, j = rows, cols
    while i > 0 and j > 0:
        if grid[i-1][j-1] == -1:
            continue
        if dp[i][j] == dp[i-1][j]:
            i -= 1
        else:
            j -= 1
        path.append((i-1, j-1))

    # Reverse the path to get the correct order
    path.reverse()

    # Return the path cost
    return sum(grid[i][j] for i, j in path)

