    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)

    def dfs(node, visited):
        visited[node] = True
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited)

    # Find all strongly connected components using Tarjan's algorithm
    stack = []
    visited = [False] * n
    low_link = [-1] * n
    scc_count = 0

    def tarjan(node):
        nonlocal scc_count
        index = len(stack)
        low_link[node] = index
        stack.append(node)
        visited[node] = True

        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                tarjan(neighbor)
                low_link[node] = min(low_link[node], low_link[neighbor])
            elif neighbor != stack[-1]:  # Backedge found
                low_link[node] = min(low_link[node], index)

        if low_link[node] == index:
            scc_count += 1
            while stack and stack[-1] != node:
                visited[stack.pop()] = False

    for i in range(n):
        if not visited[i]:
            tarjan(i)

    return scc_count

