        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, stack)
        stack.append(node)

    # Helper function to perform Tarjan's algorithm
    def tarjan(node, visited, low, parent, index, sccs):
        visited[node] = True
        index[node] = low[node] = index + 1
        stack.append(node)

        children = 0
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                children += 1
                parent[neighbor] = node
                tarjan(neighbor, visited, low, parent, index, sccs)
