def solve(data):
    n = data["n"]
    edges = data["edges"]

    # Build adjacency list representation of the graph
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)

    # Helper function to perform DFS
    def dfs(node, visited, stack):
        visited[node] = True
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, stack)
        stack.append(node)

    # Helper function to perform Tarjan's algorithm
    def tarjan(node, visited, low, index, time, sccs):
        visited[node] = True
        low[node] = index
        index += 1

        stack = []
        stack.append(node)

        while stack:
            top = stack.pop()

            for neighbor in adj_list[top]:
                if not visited[neighbor]:
                    dfs(neighbor, visited, low, index, time, sccs)
                    low[top] = min(low[top], low[neighbor])
                elif neighbor != stack[-1]:
                    low[top] = min(low[top], index)

        if low[top] == index:
            scc = []
            while stack:
                node = stack.pop()
                scc.append(node)
                visited[node] = False
            sccs.append(scc)

    # Initialize variables
    visited = [False] * n
    low = [float('inf')] * n
    index = 0
    time = 0
    sccs = []

    # Perform Tarjan's algorithm on each unvisited node
    for i in range(n):
        if not visited[i]:
            dfs(i, visited, low, index, time, sccs)

    return len(sccs)

