class Solution {
    public static int solve(Map<String,Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) return 0;

        int n = nums.size();
        int[][] dp = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = i; j < n; j++) {
                if (i == j) {
                    dp[i][j] = nums.get(i);
                } else {
                    int maxCoins = 0;
                    for (int k = i + 1; k < j; k++) {
                        int leftCoins = k > i ? dp[i][k - 1] : 1;
                        int rightCoins = k < j ? dp[k + 1][j] : 1;
                        int currentCoins = nums.get(i) * nums.get(k) * nums.get(j);
                        maxCoins = Math.max(maxCoins, leftCoins + rightCoins + currentCoins);
                    }
                    dp[i][j] = maxCoins;
                }
            }
        }
        return dp[0][n - 1];
    }

