    private static int maxCoins(List<Integer> nums) {
        if(nums.isEmpty()) return 0;

        int n = nums.size();
        int[][] dp = new int[n][n];

        // Fill the diagonal
        for(int i=0; i<n; i++) {
            dp[i][i] = nums.get(i);
        }

        // Fill the upper triangle
        for(int len=2; len<=n; len++) {
            for(int i=0; i+len-1<n; i++) {
                int j = i + len - 1;
                dp[i][j] = Integer.MIN_VALUE;

                for(int k=i+1; k<j; k++) {
                    int left = (k == i) ? 1 : dp[i][k-1];
                    int right = (k == j-1) ? 1 : dp[k+1][j];
                    dp[i][j] = Math.max(dp[i][j], left * nums.get(k) * right);
                }
            }
        }

        return dp[0][n-1];
    }
}

