class Solution {
    public static int solve(Map<String,Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if(nums == null || nums.isEmpty()) return 0;

        // Brute force approach to find the maximum total coins
        int maxCoins = 0;
        for(int i = 0; i < nums.size(); i++) {
            int left = 0;
            int right = nums.size() - 1;
            while(left < i && right > i) {
                int leftNeighbor = left == 0 ? 1 : nums.get(left - 1);
                int rightNeighbor = right == nums.size() - 1 ? 1 : nums.get(right + 1);
                int currentCoins = leftNeighbor * nums.get(i) * rightNeighbor;
                maxCoins = Math.max(maxCoins, currentCoins);
                left++;
                right--;
            }
        }

        return maxCoins;
    }

