    public static Object solve(Map<String,Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");

        if (nums == null || nums.isEmpty()) {
            return 0;
        }

        int n = nums.size();
        int[][] dp = new int[n][n];

        for (int len = 1; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                dp[i][j] = 0;

                for (int k = i + 1; k < j; k++) {
                    int left = k > 0 ? dp[i][k - 1] : 0;
                    int right = k < n - 1 ? dp[k + 1][j] : 0;

                    dp[i][j] = Math.max(dp[i][j], nums.get(i) * nums.get(k) * nums.get(j) + left + right);
                }
            }
        }

        return dp[0][n - 1];
    }
}

