        List<Integer> nums = (List<Integer>) data.get("nums");

        if (nums == null || nums.isEmpty()) {
            return 0;
        }

        int n = nums.size();
        Integer[] arr = new Integer[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nums.get(i);
        }

        Arrays.sort(arr);

        long[][] dp = new long[n][n];
        for (int len = 1; len <= n; len++) {
            for (int i = 0; i + len - 1 < n; i++) {
                int j = i + len - 1;
                long maxCoins = 0;

                for (int k = i; k <= j; k++) {
                    int leftNeighbor = k == i ? 1 : arr[k - 1];
                    int rightNeighbor = k == j ? 1 : arr[k + 1];

                    long coins = leftNeighbor * arr[k] * rightNeighbor;
                    coins += dp[i][k - 1] + dp[k + 1][j];
                    maxCoins = Math.max(maxCoins, coins);
                }

                dp[i][j] = maxCoins;
            }
        }

        return dp[0][n - 1];
    }
}

