class Solution {
    public static int solve(Map<String, Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) return 0;

        int n = nums.size();
        int[][] dp = new int[n][n];

        // Base case: single element
        for (int i = 0; i < n; i++) {
            dp[i][i] = nums.get(i);
        }

        // Fill the DP table
        for (int len = 2; len <= n; len++) {
            for (int start = 0; start <= n - len; start++) {
                int end = start + len - 1;
                int maxCoins = Integer.MIN_VALUE;

                for (int k = start; k <= end; k++) {
                    int left = start == 0 ? 1 : nums.get(start - 1);
                    int right = end == n - 1 ? 1 : nums.get(end + 1);

                    int currentCoins = left * nums.get(k) * right;
                    int remainingCoins = dp[start][k - 1] + dp[k + 1][end];

                    maxCoins = Math.max(maxCoins, currentCoins + remainingCoins);
                }

                dp[start][end] = maxCoins;
            }
        }

        return dp[0][n - 1];
    }

    public static void main(String[] args) {
        Map<String, Object> data = new HashMap<>();
        data.put("nums", Arrays.asList(3, 1, 5, 8));
        System.out.println(solve(data)); // Expected output: 167
    }
}

