public final class Solution {
    public static Object solve(Map<String,Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) return 0;

        int n = nums.size();
        Integer[] dp = new Integer[n];
        Arrays.fill(dp, -1);

        return helper(nums, 0, n - 1, dp);
    }

    private static int helper(List<Integer> nums, int start, int end, Integer[] dp) {
        if (start > end) return 0;
        if (dp[start] != null) return dp[start];

        int maxCoins = 0;
        for (int i = start; i <= end; i++) {
            int leftNeighbor = start == 0 ? 1 : nums.get(start - 1);
            int rightNeighbor = end == nums.size() - 1 ? 1 : nums.get(end + 1);
            int currentCoins = leftNeighbor * nums.get(i) * rightNeighbor + helper(nums, start, i - 1, dp) + helper(nums, i + 1, end, dp);
            maxCoins = Math.max(maxCoins, currentCoins);
        }

        dp[start] = maxCoins;
        return maxCoins;
    }
}

