class Solution {
    public static Object solve(Map<String,Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        int n = durations.size();
        Map<Integer, Integer> inDegree = new HashMap<>();
        Map<Integer, List<Integer>> adjList = new HashMap<>();

        for (int i = 0; i < n; i++) {
            inDegree.put(i, 0);
            adjList.put(i, new ArrayList<>());
        }

        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            adjList.get(u).add(v);
            inDegree.put(v, inDegree.getOrDefault(v, 0) + 1);
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (inDegree.get(i) == 0) {
                queue.offer(i);
            }
        }

        int totalDuration = 0;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            totalDuration += durations.get(u);

            for (int v : adjList.get(u)) {
                inDegree.put(v, inDegree.get(v) - 1);
                if (inDegree.get(v) == 0) {
                    queue.offer(v);
                }
            }
        }

        return totalDuration;
    }
}

