class Solution {
    public static int solve(Map<String,Object> data) {
        List<Integer> durations = new ArrayList<>();
        List<List<Integer>> edges = new ArrayList<>();

        if (data.containsKey("duration")) {
            durations.addAll((List<Integer>) data.get("duration"));
        }

        if (data.containsKey("edges")) {
            edges.addAll((List<List<Integer>>) data.get("edges"));
        }

        if (durations.isEmpty() || edges.isEmpty()) {
            return 0;
        }

        // Build the adjacency list representation of the graph
        Map<Integer, List<Integer>> graph = new HashMap<>();
        for (int i = 0; i < durations.size(); i++) {
            graph.put(i, new ArrayList<>());
        }
        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            graph.get(u).add(v);
        }

        // Topological sort to find the finishing times
        Queue<Integer> queue = new LinkedList<>();
        Map<Integer, Integer> inDegree = new HashMap<>();
        for (int i = 0; i < durations.size(); i++) {
            inDegree.put(i, 0);
        }
        for (Integer u : graph.keySet()) {
            for (Integer v : graph.get(u)) {
                inDegree.put(v, inDegree.getOrDefault(v, 0) + 1);
            }
        }

        for (int i = 0; i < durations.size(); i++) {
            if (inDegree.get(i) == 0) {
                queue.add(i);
            }
        }

        int[] finishingTimes = new int[durations.size()];
        int time = 0;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            finishingTimes[u] = time++;
            for (Integer v : graph.get(u)) {
                inDegree.put(v, inDegree.get(v) - 1);
                if (inDegree.get(v) == 0) {
                    queue.add(v);
                }
            }
        }

        // Find the maximum finishing time
        int maxTime = 0;
        for (int time : finishingTimes) {
            maxTime = Math.max(maxTime, time);
        }

        return maxTime;
    }
