public final class Solution {
    public static Object solve(Map<String,Object> data) {
        List<Integer> durations = new ArrayList<>();
        List<List<Integer>> edges = new ArrayList<>();

        if (data.containsKey("duration")) {
            durations = Arrays.asList(((List<?>) data.get("duration")).stream().mapToInt(Number::intValue).toArray());
        }

        if (data.containsKey("edges")) {
            edges = ((List<?>) data.get("edges")).stream()
                .map(edge -> Arrays.stream(edge).mapToInt(Number::intValue).boxed().collect(Collectors.toList()))
                .collect(Collectors.toList());
        }

        int n = durations.size();
        if (n == 0) {
            return 0;
        }

        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            for (List<Integer> edge : edges) {
                if (edge.get(0) == i && dp[edge.get(1)] != Integer.MAX_VALUE) {
                    dp[i] = Math.min(dp[i], dp[edge.get(1)] + durations.get(i));
                }
            }
        }

        return dp[n - 1] == Integer.MAX_VALUE ? 0 : dp[n - 1];
    }
