public final class Solution {
    public static Object solve(Map<String,Object> data) {
        int[] durations = ((List<Integer>)data.get("duration")).stream().mapToInt(Integer::intValue).toArray();
        List<List<Integer>> edges = (List<List<Integer>>)data.get("edges");

        // Edge cases
        if (durations.length == 0 || edges.isEmpty()) {
            return 0;
        }

        // Check for duplicate nodes
        Set<Integer> nodes = new HashSet<>();
        for (int d : durations) {
            if (!nodes.add(d)) {
                return 0;
            }
        }
        for (List<Integer> e : edges) {
            if (!nodes.contains(e.get(0)) || !nodes.contains(e.get(1))) {
                return 0;
            }
        }

        // Build adjacency list
        Map<Integer, List<Integer>> adjList = new HashMap<>();
        for (List<Integer> e : edges) {
            adjList.computeIfAbsent(e.get(0), k -> new ArrayList<>()).add(e.get(1));
        }

        // Topological sort
        Stack<Integer> stack = new Stack<>();
        boolean[] visited = new boolean[durations.length];
        for (int i = 0; i < durations.length; i++) {
            if (!visited[i]) {
                topologicalSort(adjList, visited, stack, i);
            }
        }

        // Calculate latest finish times
        int[] latestFinishTimes = new int[durations.length];
        while (!stack.isEmpty()) {
            int current = stack.pop();
            latestFinishTimes[current] = durations[current];
            for (Integer neighbor : adjList.getOrDefault(current, Collections.emptyList())) {
                latestFinishTimes[neighbor] = Math.max(latestFinishTimes[neighbor], latestFinishTimes[current]);
            }
        }

        // Find the maximum finish time
        int maxFinishTime = Arrays.stream(latestFinishTimes).max().orElse(0);
        return maxFinishTime;
    }

    private static void topologicalSort(Map<Integer, List<Integer>> adjList, boolean[] visited, Stack<Integer> stack, int node) {
        visited[node] = true;
        for (Integer neighbor : adjList.getOrDefault(node, Collections.emptyList())) {
            if (!visited[neighbor]) {
                topologicalSort(adjList, visited, stack, neighbor);
            }
        }
        stack.push(node);
    }
}

