class Solution {
    public static long solve(Map<String, Object> data) {
        List<Integer> durations = new ArrayList<>();
        List<List<Integer>> edges = new ArrayList<>();

        if (data.containsKey("duration")) {
            durations.addAll((List<Integer>) data.get("duration"));
        }
        if (data.containsKey("edges")) {
            edges.addAll((List<List<Integer>>) data.get("edges"));
        }

        int n = durations.size();
        if (n == 0) {
            return 0;
        }

        // Create adjacency list representation of the graph
        Map<Integer, List<Integer>> adjList = new HashMap<>();
        for (int i = 0; i < n; i++) {
            adjList.put(i, new ArrayList<>());
        }
        for (List<Integer> edge : edges) {
            adjList.get(edge.get(0)).add(edge.get(1));
        }

        // Topological sort to find the order of tasks
        Queue<Integer> queue = new LinkedList<>();
        Map<Integer, Integer> indegree = new HashMap<>();
        for (int i = 0; i < n; i++) {
            indegree.put(i, 0);
        }
        for (Integer vertex : adjList.keySet()) {
            for (Integer neighbor : adjList.get(vertex)) {
                indegree.put(neighbor, indegree.getOrDefault(neighbor, 0) + 1);
            }
        }
        for (int i = 0; i < n; i++) {
            if (indegree.get(i) == 0) {
                queue.offer(i);
            }
        }

        int time = 0;
        while (!queue.isEmpty()) {
            int current = queue.poll();
            time++;
            for (Integer neighbor : adjList.get(current)) {
                indegree.put(neighbor, indegree.get(neighbor) - 1);
                if (indegree.get(neighbor) == 0) {
                    queue.offer(neighbor);
                }
            }
        }

        // If there's a cycle, return 0
        if (time != n) {
            return 0;
        }

        // Calculate the latest start time for each task
        long[] latestStartTimes = new long[n];
        Arrays.fill(latestStartTimes, Long.MIN_VALUE);
        for (int i = 0; i < n; i++) {
            latestStartTimes[i] = time;
            for (Integer neighbor : adjList.get(i)) {
                latestStartTimes[i] = Math.max(latestStartTimes[i], latestStartTimes[neighbor]);
            }
        }

        // Calculate the total completion time
        long totalCompletionTime = 0;
        for (int i = 0; i < n; i++) {
            totalCompletionTime += latestStartTimes[i] + durations.get(i);
        }

        return totalCompletionTime;
    }
}

