class Solution {
    public static long solve(Map<String, Object> data) {
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");
        int[] durations = (int[]) data.get("duration");

        if (durations.length == 0) return 0;

        Map<Integer, Integer> startTimes = new HashMap<>();
        Map<Integer, Integer> endTimes = new HashMap<>();

        // Topological sort to find the longest path
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < durations.length; i++) {
            if (endTimes.containsKey(i)) continue;
            queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int node = queue.poll();
            for (List<Integer> edge : edges) {
                int nextNode = edge.get(1);
                if (nextNode == node || !startTimes.containsKey(nextNode)) continue;

                int endTime = Math.max(endTimes.get(node), startTimes.get(nextNode) + durations[nextNode]);
                endTimes.put(nextNode, endTime);
                if (!queue.contains(nextNode)) queue.offer(nextNode);
            }
        }

        // Find the maximum end time among all nodes
        int maxEndTime = Collections.max(endTimes.values());

        return maxEndTime;
    }
}

