public final class Solution {
    public static Object solve(Map<String,Object> data) {
        int[] durations = ((List<Integer>) data.get("duration")).stream().mapToInt(Integer::intValue).toArray();
        List<int[]> edges = ((List<List<Integer>>) data.get("edges"));

        if (durations.length == 0 || edges.isEmpty()) {
            return 0;
        }

        // Check for cycles
        Set<Integer> visited = new HashSet<>();
        Set<Integer> stack = new HashSet<>();
        boolean hasCycle = false;
        for (int i = 0; i < durations.length; i++) {
            if (!visited.contains(i)) {
                hasCycle |= detectCycle(i, visited, stack);
            }
        }
        if (hasCycle) {
            return 0;
        }

        // Topological sort
        PriorityQueue<Integer> queue = new PriorityQueue<>((a, b) -> Integer.compare(durations[b], durations[a]));
        for (int i = 0; i < durations.length; i++) {
            if (!stack.contains(i)) {
                queue.offer(i);
            }
        }

        int maxTime = 0;
        while (!queue.isEmpty()) {
            int current = queue.poll();
            maxTime = Math.max(maxTime, durations[current]);
            for (int next : edges) {
                if (next[0] == current) {
                    stack.add(next[1]);
                }
            }
        }

        return maxTime;
    }

    private static boolean detectCycle(int node, Set<Integer> visited, Set<Integer> stack) {
        visited.add(node);
        stack.add(node);
        for (int neighbor : edges) {
            if (neighbor[0] == node) {
                if (stack.contains(neighbor[1])) {
                    return true;
                } else if (!visited.contains(neighbor[1])) {
                    if (detectCycle(neighbor[1], visited, stack)) {
                        return true;
                    }
                }
            }
        }
        stack.remove(node);
        return false;
    }
}

