class Solution {
    public static Object solve(Map<String,Object> data) {
        int[] durations = (int[]) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        // Check if there are any cycles in the graph
        Set<Integer> visited = new HashSet<>();
        boolean hasCycle = false;
        for (int i = 0; i < durations.length; i++) {
            if (!visited.contains(i)) {
                hasCycle = hasCycle || detectCycle(i, visited, edges);
            }
        }

        if (hasCycle) {
            return 0; // No tasks can be finished
        }

        // Calculate the earliest completion times using topological sorting
        Arrays.sort(durations); // Sort durations in ascending order
        int[] earliestTimes = new int[durations.length];
        Arrays.fill(earliestTimes, Integer.MAX_VALUE);
        earliestTimes[0] = 0;

        for (int i = 1; i < durations.length; i++) {
            for (List<Integer> edge : edges) {
                if (edge.get(0) == i && earliestTimes[i] > earliestTimes[edge.get(1)] + durations[i]) {
                    earliestTimes[i] = earliestTimes[edge.get(1)] + durations[i];
                }
            }
        }

        // Return the maximum completion time, which will be the earliest time all tasks can finish
        return Math.max(earliestTimes);
    }

    private static boolean detectCycle(int node, Set<Integer> visited, List<List<Integer>> edges) {
        visited.add(node);

        for (List<Integer> edge : edges) {
            if (edge.get(0) == node) {
                if (visited.contains(edge.get(1))) {
                    return true; // Cycle detected
                } else if (!detectCycle(edge.get(1), visited, edges)) {
                    return true; // Cycle detected
                }
            }
        }

        visited.remove(node);
        return false;
    }
}

