        List<Integer> times = new ArrayList<>(Collections.nCopies(n, Integer.MAX_VALUE));

        // Topological sort to find the longest path
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (!containsEdge(edges, i)) {
                queue.offer(i);
                times.set(i, durations.get(i));
            }
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (List<Integer> edge : edges) {
                int from = edge.get(0), to = edge.get(1);
                if (from == current) {
                    times.set(to, Math.max(times.get(to), times.get(current) + durations.get(to)));
                }
            }
        }

        int maxTime = 0;
        for (int time : times) {
            maxTime = Math.max(maxTime, time);
        }

        return maxTime == Integer.MAX_VALUE ? 0 : maxTime;
    }

    private boolean containsEdge(List<List<Integer>> edges, int node) {
        for (List<Integer> edge : edges) {
            if (edge.get(0) == node) {
                return true;
            }
        }
        return false;
    }
