class Solution {
    public static long solve(Map<String, Object> data) {
        List<Long> durations = (List<Long>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        // Build the graph and calculate the longest path
        Map<Integer, Long> longestPath = new HashMap<>();
        Set<Integer> visited = new HashSet<>();

        for (int i = 0; i < durations.size(); i++) {
            if (!visited.contains(i)) {
                longestPath.put(i, dfs(i, longestPath, visited, durations, edges));
            }
        }

        // Find the maximum value in the longest path
        long maxDuration = 0;
        for (long duration : longestPath.values()) {
            maxDuration = Math.max(maxDuration, duration);
        }

        return maxDuration == 0 ? 0 : maxDuration - 1; // Subtract 1 to account for the start node
    }

    private static long dfs(int currentNode, Map<Integer, Long> longestPath, Set<Integer> visited, List<Long> durations, List<List<Integer>> edges) {
        if (visited.contains(currentNode)) {
            return 0;
        }
        visited.add(currentNode);

        long maxDuration = 0;
        for (List<Integer> edge : edges) {
            int neighbor = edge.get(1);
            if (neighbor != currentNode && !visited.contains(neighbor)) {
                long duration = dfs(neighbor, longestPath, visited, durations, edges);
                maxDuration = Math.max(maxDuration, duration + durations.get(currentNode));
            }
        }

        visited.remove(currentNode);
        longestPath.put(currentNode, maxDuration);
        return maxDuration;
    }
}

