public final class Solution {
    public static Object solve(Map<String, Object> data) {
        int[] duration = ((int[]) data.get("duration"));
        List<int[]> edges = (List<int[]>) data.get("edges");

        // Check for empty or minimal inputs
        if (duration == null || duration.length == 0 || edges == null || edges.isEmpty()) {
            return 0;
        }

        // Check for duplicate nodes
        Set<Integer> nodes = new HashSet<>();
        for (int[] edge : edges) {
            if (!nodes.add(edge[0]) || !nodes.add(edge[1])) {
                throw new IllegalArgumentException("Duplicate nodes found");
            }
        }

        // Check for large inputs
        if (nodes.size() > 20) {
            throw new IllegalArgumentException("Too many nodes");
        }

        // Create adjacency list representation of the graph
        Map<Integer, List<Integer>> adjList = new HashMap<>();
        for (int[] edge : edges) {
            adjList.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        }

        // Calculate the maximum duration of each task
        int[] maxDuration = new int[nodes.size()];
        for (int i = 0; i < nodes.size(); i++) {
            maxDuration[i] = duration[i];
        }

        // Use topological sorting to calculate the start times of each task
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < nodes.size(); i++) {
            if (maxDuration[i] == duration[i]) {
                queue.offer(i);
            }
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (int next : adjList.getOrDefault(current, new ArrayList<>())) {
                maxDuration[next] = Math.max(maxDuration[next], maxDuration[current] + duration[next]);
                if (--maxDuration[next] == duration[next]) {
                    queue.offer(next);
                }
            }
        }

        // Find the maximum duration among all tasks
        int maxTaskDuration = Arrays.stream(maxDuration).max().orElse(0);

        // If any task has a duration greater than its maximum possible duration, it means there's a cycle
        for (int duration : duration) {
            if (duration > maxTaskDuration) {
                return 0;
            }
        }

        // Return the total duration of all tasks
        return maxTaskDuration;
    }
