        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            for (List<Integer> edge : edges) {
                if (edge.get(0) == i && dp[i] + durations.get(i) < dp[edge.get(1)]) {
                    dp[edge.get(1)] = dp[i] + durations.get(i);
                }
            }
        }

        return dp[n - 1] != Integer.MAX_VALUE ? dp[n - 1] : 0;
    }
}

