        for (int i = n - 1; i >= 0; i--) {
            int startNode = edges.get(i).get(0);
            int endNode = edges.get(i).get(1);

            // Update the latest end time of the end node
            endTime[endNode] = Math.max(endTime[endNode], endTime[startNode] + durations.get(startNode));
        }

        // Find the maximum end time from all nodes
