class Solution {
    public static int solve(Map<String, Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        // Edge cases: empty graph, single task, multiple tasks with no dependencies
        if (durations.isEmpty() || durations.size() == 1) return durations.get(0);
        if (edges.isEmpty()) return 0;

        // Build the adjacency list representation of the graph
        Map<Integer, List<Integer>> adjList = new HashMap<>();
        for (int i = 0; i < durations.size(); i++) {
            adjList.put(i, new ArrayList<>());
        }
        for (List<Integer> edge : edges) {
            adjList.get(edge.get(0)).add(edge.get(1));
        }

        // Topological sort using Kahn's algorithm
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < durations.size(); i++) {
            if (adjList.get(i).isEmpty()) queue.add(i);
        }

        int[] inDegree = new int[durations.size()];
        for (int i = 0; i < durations.size(); i++) {
            inDegree[i] = adjList.get(i).size();
        }

        int maxTime = 0;
        while (!queue.isEmpty()) {
            int current = queue.poll();
            maxTime = Math.max(maxTime, durations.get(current));

            for (int neighbor : adjList.get(current)) {
                inDegree[neighbor]--;
                if (inDegree[neighbor] == 0) queue.add(neighbor);
            }
        }

        // Check if there are any cycles
        for (int degree : inDegree) {
            if (degree > 0) return -1; // Cycle detected
        }

        return maxTime;
    }
}

