import java.util.*;

class Solution {
    public static Object solve(Map<String, Object> data) {
        int[] durations = (int[]) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        // Edge cases
        if (durations.length == 0 || edges.isEmpty()) {
            return 0;
        }

        // Check if the graph is valid
        Set<Integer> nodes = new HashSet<>();
        for (List<Integer> edge : edges) {
            nodes.add(edge.get(0));
            nodes.add(edge.get(1));
        }
        if (nodes.size() != durations.length) {
            throw new IllegalArgumentException("Invalid graph");
        }

        // Calculate the maximum duration of any task
        int maxDuration = Arrays.stream(durations).max().getAsInt();

        // Create a priority queue to store nodes with their start times
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> a.start - b.start);
        for (int i = 0; i < durations.length; i++) {
            pq.offer(new Node(i, 0, durations[i]));
        }

        int endtime = 0;
        while (!pq.isEmpty()) {
            Node current = pq.poll();
            endtime = Math.max(endtime, current.end);
            for (List<Integer> edge : edges) {
                if (edge.get(0) == current.id) {
                    pq.offer(new Node(edge.get(1), current.end + current.duration, durations[edge.get(1)]));
                }
            }
        }

        return endtime;
    }

    static class Node implements Comparable<Node> {
        int id;
        int start;
        int duration;

        Node(int id, int start, int duration) {
            this.id = id;
            this.start = start;
            this.duration = duration;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.start, other.start);
        }
    }
}

