class Solution {
    public static Object solve(Map<String, Object> data) {
        List<Integer> durations = (List<Integer>) data.get("duration");
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");

        if (durations == null || durations.isEmpty()) {
            return 0;
        }

        int n = durations.size();
        List<Integer> times = new ArrayList<>(Collections.nCopies(n, Integer.MAX_VALUE));
        Map<Integer, List<Integer>> adjList = new HashMap<>();

        // Build adjacency list from edges
        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);
            adjList.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        }

        // Topological sort to find the earliest start time
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            if (!adjList.containsKey(i)) {
                queue.add(i);
                times.set(i, durations.get(i));
            }
        }

        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (int neighbor : adjList.getOrDefault(current, Collections.emptyList())) {
                times.set(neighbor, Math.max(times.get(neighbor), times.get(current) + durations.get(neighbor)));
                if (--inDegree[neighbor] == 0) {
                    queue.add(neighbor);
                }
            }
        }

        // Find the maximum end time
        int maxEndTime = 0;
        for (int time : times) {
            maxEndTime = Math.max(maxEndTime, time);
        }

        return maxEndTime == Integer.MAX_VALUE ? 0 : maxEndTime;
    }
